namespace sv_e4ca6010bed9469e855a880f9b31ae9e.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service (one per circuit) that holds theme state and notifies subscribers on change.
/// </summary>
public class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChanged;

    public void SetTheme(ThemeMode theme, string accentColor)
    {
        var changed = _theme != theme || _accentColor != accentColor;
        _theme = theme;
        _accentColor = accentColor;
        if (changed) NotifyChanged();
    }

    private void NotifyChanged() => OnChanged?.Invoke();
}

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService
@inject IJSRuntime JS

@* This small interactive component lives in the static layout and bridges
   ThemeService changes to the DOM via JS interop. *@

<span class="theme-indicator badge bg-secondary ms-2">@ThemeLabel</span>

@code {
    private string ThemeLabel => ThemeService.Theme switch
    {
        ThemeMode.Light => "☀️ Light",
        ThemeMode.Dark => "🌙 Dark",
        _ => "💻 System"
    };

    protected override void OnInitialized()
    {
        ThemeService.OnChanged += HandleThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await ApplyThemeToDOM();
        }
    }

    private async void HandleThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            StateHasChanged();
            await ApplyThemeToDOM();
        });
    }

    private async Task ApplyThemeToDOM()
    {
        try
        {
            await JS.InvokeVoidAsync("themeInterop.apply",
                ThemeService.Theme.ToString().ToLowerInvariant(),
                ThemeService.AccentColor);
        }
        catch (JSDisconnectedException) { }
    }

    public void Dispose()
    {
        ThemeService.OnChanged -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 500px;">
    <h4>Theme</h4>
    <div class="btn-group mb-3" role="group">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <button class="btn @(ThemeService.Theme == mode ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => ThemeService.Theme = mode">
                @mode
            </button>
        }
    </div>

    <h4>Accent Color</h4>
    <div class="d-flex align-items-center gap-3 mb-3">
        <input type="color" class="form-control form-control-color"
               value="@ThemeService.AccentColor"
               @onchange="OnAccentChanged" />
        <span>@ThemeService.AccentColor</span>
    </div>

    <p class="text-muted">
        Changes apply instantly to all components across the app.
    </p>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChanged += StateHasChanged;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    public void Dispose()
    {
        ThemeService.OnChanged -= StateHasChanged;
    }
}

window.themeInterop = {
    apply: function (mode, accentColor) {
        const html = document.documentElement;
        html.setAttribute('data-bs-theme', mode === 'system' ? getSystemTheme() : mode);
        html.style.setProperty('--app-accent-color', accentColor);
    }
};

function getSystemTheme() {
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

// React to OS theme changes when in "system" mode
window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', function () {
    const current = document.documentElement.getAttribute('data-bs-theme');
    if (current === 'light' || current === 'dark') return; // user explicitly chose
    document.documentElement.setAttribute('data-bs-theme', getSystemTheme());
});

