window.themeInterop = {
    apply: function (mode, accentColor) {
        const html = document.documentElement;
        html.setAttribute('data-bs-theme', mode === 'system' ? getSystemTheme() : mode);
        html.style.setProperty('--app-accent-color', accentColor);
    }
};

function getSystemTheme() {
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

// React to OS theme changes when in "system" mode
window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', function () {
    const current = document.documentElement.getAttribute('data-bs-theme');
    if (current === 'light' || current === 'dark') return;
    document.documentElement.setAttribute('data-bs-theme', getSystemTheme());
});

